<script setup>import {ref,onMounted,onBeforeUnmount} from 'vue';import * as echarts from 'echarts';import {adminApi} from '../../api/blog';const stats=ref({}),chart=ref(),el=ref();onMounted(async()=>{stats.value=await adminApi.overview();const d=await adminApi.trend();chart.value=echarts.init(el.value);chart.value.setOption({tooltip:{},xAxis:{type:'category',data:d.dates},yAxis:{type:'value',minInterval:1},series:[{type:'line',smooth:true,data:d.counts,areaStyle:{}}]})});onBeforeUnmount(()=>chart.value?.dispose())</script><template><h1>数据控制台</h1><div class="stats"><div class="stat">文章总数<strong>{{stats.articleCount||0}}</strong></div><div class="stat">分类数量<strong>{{stats.categoryCount||0}}</strong></div><div class="stat">已发布<strong>{{stats.publishedCount||0}}</strong></div><div class="stat">草稿箱<strong>{{stats.draftCount||0}}</strong></div></div><div class="chart"><h3>近七日发布趋势</h3><div ref="el" style="height:300px"></div></div></template>
